cd output && python3 - <<'EOF'
import docx
d = docx.Document("offer_letter_filled.docx")
def allparts(doc):
    for p in doc.paragraphs: yield ("body",p)
    for t in doc.tables:
        for r in t.rows:
            for c in r.cells:
                for p in c.paragraphs: yield ("table",p)
                for nt in c.tables:
                    for rr in nt.rows:
                        for cc in rr.cells:
                            for p in cc.paragraphs: yield("nested",p)
    for s in doc.sections:
        for nm,part in [("hdr",s.header),("fph",s.first_page_header),("eph",s.even_page_header),("ftr",s.footer),("fpf",s.first_page_footer),("epf",s.even_page_footer)]:
            if part:
                for p in part.paragraphs: yield(nm,p)
                for t in part.tables:
                    for r in t.rows:
                        for c in r.cells:
                            for p in c.paragraphs: yield(nm+"-tbl",p)
for loc,p in allparts(d):
    if "Côte" in p.text or "Montr" in p.text or "18 " in p.text:
        print(loc, repr(p.text))
EOF
